    /// <summary>
    /// Specifies the configuration of the built-in Amazon.QnAIntent . The AMAZON.QnAIntent intent is called when Amazon Lex can't determine another intent to invoke. If you specify this field, you can't spec- ify the kendraConfiguration field. dataSourceConfiguration -&gt; (structure) Contains details about the configuration of the data source used for the AMAZON.QnAIntent . opensearchConfiguration -&gt; (structure) Contains details about the configuration of the Amazon OpenSearch Service database used for the AMAZON.QnAIntent . To create a domain, follow the steps at Creating and managing Amazon OpenSearch Service domains . domainEndpoint -&gt; (string) [required] The endpoint of the Amazon OpenSearch Service domain. Constraints: o pattern: ^(http|https):\/\/+[^\s]+[\w] indexName -&gt; (string) [required] The name of the Amazon OpenSearch Service index. Constraints: o min: 1 o max: 255 o pattern: ^(?![_-])[a-z0-9][a-z0-9_\-]{0,254}$ exactResponse -&gt; (boolean) Specifies whether to return an exact response or to re- turn an answer generated by the model using the fields you specify from the database. exactResponseFields -&gt; (structure) Contains the names of the fields used for an exact re- sponse to the user. questionField -&gt; (string) [required] The name of the field that contains the query made to the OpenSearch Service database. answerField -&gt; (string) [required] The name of the field that contains the answer to the query made to the OpenSearch Service database. includeFields -&gt; (list) Contains a list of fields from the Amazon OpenSearch Ser- vice that the model can use to generate the answer to the query. Constraints: o min: 1 o max: 5 (string) kendraConfiguration -&gt; (structure) Contains details about the configuration of the Amazon Kendra index used for the AMAZON.QnAIntent . To create a Amazon Kendra index, follow the steps at Creating an index . kendraIndex -&gt; (string) [required] The ARN of the Amazon Kendra index to use. Constraints: o min: 32 o max: 2048 o pattern: ^arn:aws:kendra:[a-z]+-[a-z]+-[0-9]:[0-9]{12}:in- dex\/[a-zA-Z0-9][a-zA-Z0-9_-]*$ queryFilterStringEnabled -&gt; (boolean) Specifies whether to enable an Amazon Kendra filter string or not. queryFilterString -&gt; (string) Contains the Amazon Kendra filter string to use if en- abled. For more information on the Amazon Kendra search filter JSON format, see Using document attributes to fil- ter search results . Constraints: o min: 1 o max: 5000 exactResponse -&gt; (boolean) Specifies whether to return an exact response from the Amazon Kendra index or to let the Amazon Bedrock model you select generate a response based on the results. To use this feature, you must first add FAQ questions to your index by following the steps at Adding frequently asked questions (FAQs) to an index . bedrockKnowledgeStoreConfiguration -&gt; (structure) Contains details about the configuration of the Amazon Bedrock knowledge base used for the AMAZON.QnAIntent . To set up a knowledge base, follow the steps at Building a knowledge base . bedrockKnowledgeBaseArn -&gt; (string) [required] The base ARN of the knowledge base used. Constraints: o min: 1 o max: 200 o pattern: ^arn:aws(-[^:]+)?:bedrock:[a-z0-9-]{1,40}:[0-9]{12}:knowl- edge-base\/[A-Za-z0-9]{10}$|^[A-Za-z0-9]{10}$ exactResponse -&gt; (boolean) Specifies whether to return an exact response, or to re- turn an answer generated by the model, using the fields you specify from the database. exactResponseFields -&gt; (structure) Contains the names of the fields used for an exact re- sponse to the user. answerField -&gt; (string) The answer field used for an exact response from Bedrock Knowledge Store. bedrockModelConfiguration -&gt; (structure) Contains information about the Amazon Bedrock model used to in- terpret the prompt used in descriptive bot building. modelArn -&gt; (string) [required] The ARN of the foundation model used in descriptive bot building. Constraints: o pattern: ^arn:aws(-[^:]+)?:bedrock:[a-z0-9-]{1,20}::founda- tion-model\/[a-z0-9-]{1,63}[.]{1}([a-z0-9-]{1,63}[.]){0,2}[a-z0-9-]{1,63}([:][a-z0-9-]{1,63}){0,2}$ guardrail -&gt; (structure) The guardrail configuration in the Bedrock model specifica- tion details. identifier -&gt; (string) [required] The unique guardrail id for the Bedrock guardrail config- uration. Constraints: o min: 1 o max: 2048 o pattern: ^(([a-z0-9]+)|(arn:aws(-[^:]+)?:bedrock:[a-z0-9-]{1,20}:[0-9]{12}:guardrail/[a-z0-9]+))$ version -&gt; (string) [required] The guardrail version for the Bedrock guardrail configu- ration. Constraints: o pattern: ^(([1-9][0-9]{0,7})|(DRAFT))$ traceStatus -&gt; (string) The Bedrock trace status in the Bedrock model specification details. Possible values: o ENABLED o DISABLED customPrompt -&gt; (string) The custom prompt used in the Bedrock model specification de- tails. Constraints: o min: 1 o max: 4000 JSON Syntax: { "dataSourceConfiguration": { "opensearchConfiguration": { "domainEndpoint": "string", "indexName": "string", "exactResponse": true|false, "exactResponseFields": { "questionField": "string", "answerField": "string" }, "includeFields": ["string", ...] }, "kendraConfiguration": { "kendraIndex": "string", "queryFilterStringEnabled": true|false, "queryFilterString": "string", "exactResponse": true|false }, "bedrockKnowledgeStoreConfiguration": { "bedrockKnowledgeBaseArn": "string", "exactResponse": true|false, "exactResponseFields": { "answerField": "string" } } }, "bedrockModelConfiguration": { "modelArn": "string", "guardrail": { "identifier": "string", "version": "string" }, "traceStatus": "ENABLED"|"DISABLED", "customPrompt": "string" } }
    /// </summary>
    [CliOption("--qn-a-intent-configuration")]
    public string? QnAIntentConfiguration { get; set; }

    /// <summary>
    /// Qinconnect intent configuration details for the create intent re- quest. qInConnectAssistantConfiguration -&gt; (structure) The Qinconnect assistant configuration details of the Qinconnect intent. assistantArn -&gt; (string) [required] The assistant Arn details of the Qinconnect assistant config- uration. Constraints: o pattern: ^arn:[a-z-]*?:wis- dom:[a-z0-9-]*?:[0-9]{12}:[a-z-]*?/[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}(?:/[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}){0,2}$ Shorthand Syntax: qInConnectAssistantConfiguration={assistantArn=string} JSON Syntax: { "qInConnectAssistantConfiguration": { "assistantArn": "string" } }
    /// </summary>
    [CliOption("--q-in-connect-intent-configuration")]
    public string? QInConnectIntentConfiguration { get; set; }

